#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
# Count the inputs of every non-coinbase transaction in blocks H0..H1 (inclusive) from a local monerod RPC.
# usage: window_inputs.py <rpc url> <h0> <h1>
# Prints per block: height, tx count, max inputs, number of txs with >= 8 inputs; then a histogram of input counts.
import json, sys, urllib.request, collections

url, h0, h1 = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])

def post(path, body):
    req = urllib.request.Request(url + path, data=json.dumps(body).encode(), headers={"Content-Type": "application/json"})
    return json.load(urllib.request.urlopen(req, timeout=600))

hist = collections.Counter()
heavy_blocks = 0
for h in range(h0, h1 + 1):
    r = post("/json_rpc", {"jsonrpc": "2.0", "id": "0", "method": "get_block", "params": {"height": h}})["result"]
    hashes = r.get("tx_hashes", []) or []
    mx, n8 = 0, 0
    for i in range(0, len(hashes), 200):
        t = post("/get_transactions", {"txs_hashes": hashes[i:i + 200], "decode_as_json": True, "prune": True})
        for tx in t.get("txs", []):
            n = len(json.loads(tx["as_json"])["vin"])
            hist[n] += 1
            mx = max(mx, n)
            n8 += n >= 8
    heavy_blocks += n8 > 0
    print(f"{h} txs {len(hashes)} max_inputs {mx} txs_ge8 {n8}", flush=True)
print(f"blocks with a >=8-input tx: {heavy_blocks} of {h1 - h0 + 1}")
print("inputs histogram:", dict(sorted(hist.items())))
